// The simulated load of the tiles (tests/load_schedule.hpp, agent 38) on costs made by hand: the
// workers take the tiles in their order, the updates show the tiles generated by then within
// their budget, in order; the last tile shown within a reach.
#include "load_schedule.hpp"

#include "test_assert.hpp"

#include <stdexcept>
#include <vector>

namespace {

bool near(double a, double b) {
    return a > b - 1e-9 && a < b + 1e-9;
}

// One worker: the tiles one after the other; each shown at the first update after it.
void testOneWorker() {
    const std::vector<double> costs{0.01, 0.02, 0.0};
    const std::vector<double> shown = load_schedule::simulate(costs, {1, 8, 0.1});
    TEST_CHECK(shown.size() == 3);
    TEST_CHECK(near(shown[0], 0.1) && near(shown[1], 0.1) && near(shown[2], 0.1));
    const std::vector<double> slow = load_schedule::simulate(std::vector<double>{0.15, 0.1},
                                                             {1, 8, 0.1});
    TEST_CHECK(near(slow[0], 0.2) && near(slow[1], 0.3));
}

// Two workers take the next tile as soon as they are free; the budget of an update holds the
// rest for the next ones, in their order.
void testWorkersAndBudget() {
    const std::vector<double> costs{0.3, 0.1, 0.1, 0.1, 0.0};
    const std::vector<double> shown = load_schedule::simulate(costs, {2, 8, 0.1});
    // worker 0: tile 0 until 0.3; worker 1: tiles 1, 2, 3 at 0.1, 0.2, 0.3, then tile 4 at 0.3.
    TEST_CHECK(near(shown[0], 0.3) && near(shown[1], 0.1) && near(shown[2], 0.2));
    TEST_CHECK(near(shown[3], 0.3) && near(shown[4], 0.3));
    const std::vector<double> zero(5, 0.0);
    const std::vector<double> budget = load_schedule::simulate(zero, {4, 2, 0.1});
    TEST_CHECK(near(budget[0], 0.0) && near(budget[1], 0.0) && near(budget[2], 0.1) &&
               near(budget[3], 0.1) && near(budget[4], 0.2));
}

void testLastShown() {
    std::vector<load_schedule::Tile> tiles(3);
    tiles[0].distanceChunks = 0;
    tiles[1].distanceChunks = 3;
    tiles[2].distanceChunks = 20;
    const std::vector<double> shown{0.5, 0.2, 0.9};
    TEST_CHECK(near(load_schedule::lastShown(tiles, shown, 2), 0.5));
    TEST_CHECK(near(load_schedule::lastShown(tiles, shown, 4), 0.5));
    TEST_CHECK(near(load_schedule::lastShown(tiles, shown, -1), 0.9));
    TEST_CHECK(load_schedule::lastShown(std::vector<load_schedule::Tile>{}, shown, 4) < 0.0);
}

void testInvalid() {
    bool thrown = false;
    try {
        static_cast<void>(load_schedule::simulate(std::vector<double>{-1.0}, {}));
    } catch (const std::invalid_argument&) {
        thrown = true;
    }
    TEST_CHECK(thrown);
}

} // namespace

int main() {
    testOneWorker();
    testWorkersAndBudget();
    testLastShown();
    testInvalid();
    return test::result();
}
